IMAGE_SIZES = ("", "s", "m", "l")
IMAGES_PER_BATCH = 10_000
IMAGES_PER_ITEM = 1_000_000
_OPEN_ZIPFILES = {}


def _padded_id(value, width):
    value = int(value)
    if value < 0 or value >= 10**width:
        raise ValueError(f"identifier must fit in {width} digits")
    return f"{value:0{width}d}"


def log(*args):
    print(" ".join(str(arg) for arg in args))


def _size_prefix(size):
    size = (size or "").lower()
    if size not in IMAGE_SIZES:
        raise ValueError("size must be one of '', 's', 'm', or 'l'")
    return f"{size}_" if size else ""


def _cover_filename(cover_id, size="", ext="jpg"):
    cover_id = _padded_id(cover_id, 10)
    suffix = f"-{size.upper()}" if size else ""
    return f"{cover_id}{suffix}.{ext.lstrip('.') or 'jpg'}"


class Cover:
    """A cover record and helpers for its canonical archive.org location."""

    def __init__(self, cover=None, **kwargs):
        if cover is None:
            attributes = {}
        elif hasattr(cover, "items"):
            attributes = dict(cover.items())
        elif hasattr(cover, "__dict__"):
            attributes = vars(cover).copy()
        else:
            raise TypeError("cover must be a mapping or cover record")
        attributes.update(kwargs)
        self.__dict__.update(attributes)

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        """Return the zero-padded four-digit item and two-digit batch IDs."""
        cover_id = _padded_id(cover_id, 10)
        return cover_id[:4], cover_id[4:6]

    @staticmethod
    def get_cover_url(cover_id, size="", ext="jpg", protocol="https"):
        """Return the direct archive.org URL for a cover inside its batch zip."""
        size = (size or "").lower()
        prefix = _size_prefix(size)
        protocol = (protocol or "https").rstrip(":/").lower()
        if protocol not in ("http", "https"):
            raise ValueError("protocol must be 'http' or 'https'")

        padded_id = _padded_id(cover_id, 10)
        item_id, batch_id = padded_id[:4], padded_id[4:6]
        item = f"{prefix}covers_{item_id}"
        archive_name = f"{item}_{batch_id}.{ext.lstrip('.') or 'jpg'}"
        filename = _cover_filename(cover_id, size, ext)
        return (
            f"{protocol}://archive.org/download/{item}/{archive_name}/{filename}"
        )

    def get_url(self, size="", ext="jpg", protocol="https"):
        return self.get_cover_url(self.id, size, ext, protocol)

    def get_filename(self, size=""):
        field = "filename" + (f"_{size.lower()}" if size else "")
        return getattr(self, field, None)

    def is_valid_file(self):
        """Return whether all available local image files for this cover exist."""
        from openlibrary.coverstore.coverlib import find_image_path

        filenames = [self.get_filename(size) for size in IMAGE_SIZES]
        filenames = [name for name in filenames if name]

        def exists(filename):
            if filename.startswith(("http://", "https://")):
                return True
            path = find_image_path(filename)
            if ".zip/" in path:
                zip_path, member = path.split(".zip/", 1)
                try:
                    with zipfile.ZipFile(zip_path + ".zip") as archive:
                        archive.getinfo(member)
                    return True
                except (OSError, KeyError, zipfile.BadZipFile):
                    return False
            return os.path.isfile(path)

        return bool(filenames) and all(exists(name) for name in filenames)

    def delete_files(self):
        """Remove this cover's local source images, if they still exist."""
        from openlibrary.coverstore.coverlib import find_image_path

        for size in IMAGE_SIZES:
            filename = self.get_filename(size)
            if filename and not filename.startswith(("http://", "https://")):
                path = find_image_path(filename)
                if os.path.isfile(path):
                    os.remove(path)


class CoverDB:
    """Database operations for archival state and completed batches."""

    def __init__(self, database=None):
        self.db = database if database is not None else db.getdb()

    def get_unarchived(self, limit=10_000):
        return self.db.select(
            "cover",
            where="archived=$false AND failed=$failed",
            vars={"false": False, "failed": False},
            order="id",
            limit=limit,
        )

    def get_archived(self, start_id, end_id):
        return self.db.select(
            "cover",
            where="id >= $start_id AND id <= $end_id AND archived=$true",
            vars={"start_id": start_id, "end_id": end_id, "true": True},
            order="id",
        )

    def get_failed(self, start_id=None, end_id=None):
        where = "failed=$true"
        variables = {"true": True}
        if start_id is not None:
            where += " AND id >= $start_id"
            variables["start_id"] = start_id
        if end_id is not None:
            where += " AND id <= $end_id"
            variables["end_id"] = end_id
        return self.db.select("cover", where=where, vars=variables, order="id")

    @staticmethod
    def _get_batch_end_id(start_id):
        """Return the last cover ID in the 10,000-ID batch containing start_id."""
        start_id = int(start_id)
        return ((start_id // IMAGES_PER_BATCH) + 1) * IMAGES_PER_BATCH - 1

    def mark_archived(self, cover_id, filenames):
        values = {
            "archived": True,
            "uploaded": False,
            "filename": filenames[""],
            "filename_s": filenames["s"],
            "filename_m": filenames["m"],
            "filename_l": filenames["l"],
        }
        self.db.update(
            "cover", where="id=$cover_id", vars={"cover_id": cover_id}, **values
        )

    def mark_failed(self, cover_id):
        self.db.update(
            "cover",
            where="id=$cover_id",
            vars={"cover_id": cover_id},
            failed=True,
        )

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext="jpg"):
        """Store verified archive.org URLs for every good cover in a batch."""
        CoverDB()._update_completed_batch(item_id, batch_id, ext)

    def _update_completed_batch(self, item_id, batch_id, ext="jpg"):
        item_id, batch_id = int(item_id), int(batch_id)
        start_id = item_id * IMAGES_PER_ITEM + batch_id * IMAGES_PER_BATCH
        end_id = self._get_batch_end_id(start_id)
        covers = self.db.select(
            "cover",
            where=(
                "id >= $start_id AND id <= $end_id "
                "AND archived=$archived AND failed=$failed"
            ),
            vars={
                "start_id": start_id,
                "end_id": end_id,
                "archived": True,
                "failed": False,
            },
            order="id",
        )

        for cover in covers:
            cover_id = int(cover.id)
            self.db.update(
                "cover",
                where="id=$cover_id",
                vars={"cover_id": cover_id},
                uploaded=True,
                filename=Cover.get_cover_url(cover_id, ext=ext),
                filename_s=Cover.get_cover_url(cover_id, size="s", ext=ext),
                filename_m=Cover.get_cover_url(cover_id, size="m", ext=ext),
                filename_l=Cover.get_cover_url(cover_id, size="l", ext=ext),
            )


class Batch:
    """A 10,000-cover batch within one archive.org item."""

    def __init__(self, item_id, batch_id, size=None):
        self.item_id = item_id
        self.batch_id = batch_id
        self.size = size.lower() if size is not None else None
        if self.size is not None:
            _size_prefix(self.size)

    def _norm_ids(self):
        return _padded_id(self.item_id, 4), _padded_id(self.batch_id, 2)

    @classmethod
    def get_relpath(cls, item_id, batch_id, size="", ext="zip"):
        size = (size or "").lower()
        prefix = _size_prefix(size)
        item_id, batch_id = _padded_id(item_id, 4), _padded_id(batch_id, 2)
        item = f"{prefix}covers_{item_id}"
        filename = f"{item}_{batch_id}.{ext.lstrip('.') or 'zip'}"
        return os.path.join("items", item, filename)

    @classmethod
    def get_abspath(cls, item_id, batch_id, size="", ext="zip"):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @property
    def start_id(self):
        item_id, batch_id = self._norm_ids()
        return int(item_id) * IMAGES_PER_ITEM + int(batch_id) * IMAGES_PER_BATCH

    @property
    def item_name(self):
        item_id, _ = self._norm_ids()
        return f"{_size_prefix(self.size or '')}covers_{item_id}"

    @contextmanager
    def lock(self):
        """Serialize work on this batch across archival processes."""
        item_id, batch_id = self._norm_ids()
        lock_dir = os.path.join(config.data_root, ".locks")
        os.makedirs(lock_dir, exist_ok=True)
        lock_path = os.path.join(lock_dir, f"covers_{item_id}_{batch_id}.lock")
        with open(lock_path, "a") as lock_file:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)

    @classmethod
    def finalize(cls, start_id, test=False, ext="jpg"):
        """Mark an uploaded batch complete and remove its local zip files."""
        item_id, batch_id = Cover.id_to_item_and_batch_id(start_id)
        batch = cls(int(item_id), int(batch_id))
        if test:
            return
        with batch.lock():
            cls._finalize_locked(item_id, batch_id, ext)

    @staticmethod
    def _finalize_locked(item_id, batch_id, ext="jpg"):
        CoverDB.update_completed_batch(item_id, batch_id, ext=ext)
        for size in IMAGE_SIZES:
            path = Batch.get_abspath(item_id, batch_id, size)
            if os.path.isfile(path):
                os.remove(path)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        """Upload local batch zips, verify them remotely, and optionally finalize."""
        uploader = uploader or Uploader
        item_id, batch_id = self._norm_ids()
        sizes = (self.size,) if self.size is not None else IMAGE_SIZES


        with self.lock():
            for size in sizes:
                path = self.get_abspath(item_id, batch_id, size)
                filename = os.path.basename(path)
                item = f"{_size_prefix(size)}covers_{item_id}"

                if not os.path.isfile(path):
                    continue
                if upload and not test and not uploader.is_uploaded(item, filename):
                    uploader.upload(item, [path])
                if upload and not test:
                    # The upload response is not proof of completion: verify the
                    # exact zip filename in the target item before finalizing.
                    if not uploader.is_uploaded(item, filename):
                        log("upload not yet visible", item, filename)

            if finalize and not test:
                all_uploaded = all(
                    uploader.is_uploaded(
                        f"{_size_prefix(size)}covers_{item_id}",
                        os.path.basename(self.get_abspath(item_id, batch_id, size)),
                    )
                    for size in IMAGE_SIZES
                )
                if all_uploaded:
                    self._finalize_locked(item_id, batch_id, "jpg")
                else:
                    log("batch is not fully uploaded", item_id, batch_id)


def _zip_relpath(name):
    """Resolve an image name or zip filename to its canonical relative path."""
    name = os.fspath(name)
    normalized = name.replace("\\", "/")
    if normalized.startswith("items/") and normalized.lower().endswith(".zip"):
        return normalized
    if os.path.isabs(name):
        root = os.path.abspath(config.data_root)
        absolute = os.path.abspath(name)
        if os.path.commonpath((root, absolute)) == root:
            relative = os.path.relpath(absolute, root).replace(os.sep, "/")
            if relative.startswith("items/") and relative.lower().endswith(".zip"):
                return relative

    basename = os.path.basename(normalized)
    match = re.fullmatch(r"(?:[sml]_)?covers_(\d{4})_(\d{2})\.zip", basename)
    if match:
        prefix = basename.split("covers_", 1)[0]
        return os.path.join(
            "items",
            f"{prefix}covers_{match.group(1)}",
            basename,
        )

    match = re.fullmatch(r"(\d{10})(?:-([SML]))?\.[^.]+", basename)
    if not match:
        raise ValueError(f"cannot determine cover batch from {name!r}")
    cover_id = int(match.group(1))
    item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
    size = (match.group(2) or "").lower()
    return Batch.get_relpath(item_id, batch_id, size)


def open_zipfile(name):
    """Open a batch zip for append, creating its parent directory as needed."""
    relpath = _zip_relpath(name)
    path = os.path.join(config.data_root, relpath)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, mode="a", compression=zipfile.ZIP_STORED)


def get_zipfile(name):
    """Return a cached open zip archive for an image or batch filename."""
    relpath = _zip_relpath(name)
    archive = _OPEN_ZIPFILES.get(relpath)
    if archive is None or archive.fp is None:
        archive = open_zipfile(relpath)
        _OPEN_ZIPFILES[relpath] = archive
    return archive


class ZipManager:
    """Write uncompressed, deduplicated cover batch zip archives."""

    def __init__(self):
        self.zipfiles = {}
        self.added_files = {}

    def add_file(self, name, filepath, mtime):
        relpath = _zip_relpath(name)
        archive = self.zipfiles.get(relpath)
        if archive is None or archive.fp is None:
            archive = get_zipfile(name)
            self.zipfiles[relpath] = archive
            self.added_files[relpath] = set(archive.namelist())

        if name in self.added_files[relpath]:
            return f"{relpath}/{name}"

        timestamp = time.localtime(float(mtime))[:6]
        # ZIP stores local timestamps and does not support years before 1980.
        if timestamp[0] < 1980:
            timestamp = (1980, 1, 1, 0, 0, 0)
        elif timestamp[0] > 2107:
            timestamp = (2107, 12, 31, 23, 59, 58)
        info = zipfile.ZipInfo(name, date_time=timestamp)
        info.compress_type = zipfile.ZIP_STORED
        info.external_attr = 0o100644 << 16
        with open(filepath, "rb") as source:
            archive.writestr(info, source.read())
        self.added_files[relpath].add(name)
        return f"{relpath}/{name}"

    def close(self):
        for relpath, archive in self.zipfiles.items():
            if archive.fp is not None:
                archive.close()
            if _OPEN_ZIPFILES.get(relpath) is archive:
                del _OPEN_ZIPFILES[relpath]
        self.zipfiles.clear()
        self.added_files.clear()


class Uploader:
    """Thin wrapper around the Internet Archive command line client."""

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        try:
            result = subprocess.run(
                ["ia", "list", item],
                text=True,
                capture_output=True,
                check=True,
            )
        except (OSError, subprocess.CalledProcessError) as error:
            if verbose:
                log("unable to check upload", item, zip_filename, error)
            return False
        filenames = {
            line.strip().split()[-1]
            for line in result.stdout.splitlines()
            if line.strip()
        }
        uploaded = zip_filename in filenames
        if verbose:
            log(item, zip_filename, "uploaded" if uploaded else "not uploaded")
        return uploaded

    @staticmethod
    def upload(itemname, filepaths):
        filepaths = list(filepaths)
        if not filepaths:
            return None
        return subprocess.run(
            ["ia", "upload", itemname, *filepaths, "--retries", "10"],
            text=True,
            capture_output=True,
            check=True,
        )


def count_files_in_zip(filepath):
    """Count JPEG image members in a batch zip."""
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith((".jpg", ".jpeg")) for name in archive.namelist())


def archive(test=True):
    """Create local batch zips from unarchived cover images.

    In non-test mode, records are moved to the local zip references and source
    files are removed only after the zip is closed successfully. Uploading and
    remote finalization are handled by :meth:`Batch.process_pending`.
    """
    covers_db = CoverDB()
    candidates = covers_db.get_unarchived()
    batch_ids = sorted(
        {
            (
                int(cover.id) // IMAGES_PER_ITEM,
                (int(cover.id) % IMAGES_PER_ITEM) // IMAGES_PER_BATCH,
            )
            for cover in candidates
        }
    )

    for item_id, batch_id in batch_ids:
        batch = Batch(item_id, batch_id)
        with batch.lock():
            pending = covers_db.db.select(
                "cover",
                where=(
                    "id >= $start_id AND id <= $end_id "
                    "AND archived=$archived AND failed=$failed"
                ),
                vars={
                    "start_id": batch.start_id,
                    "end_id": batch.start_id + IMAGES_PER_BATCH - 1,
                    "archived": False,
                    "failed": False,
                },
                order="id",
                limit=IMAGES_PER_BATCH,
            )
            if not pending:
                continue

            manager = ZipManager()
            archived = []
            missing = []
            try:
                for row in pending:
                    cover = Cover(row)
                    files = {
                        "": cover.get_filename(""),
                        "s": cover.get_filename("s"),
                        "m": cover.get_filename("m"),
                        "l": cover.get_filename("l"),
                    }
                    paths = {
                        size: (
                            os.path.join(config.data_root, "localdisk", filename)
                            if filename
                            else None
                        )
                        for size, filename in files.items()
                    }
                    if any(not path or not os.path.isfile(path) for path in paths.values()):
                        print(
                            "Missing image file for %010d" % int(row.id),
                            file=web.debug,
                        )
                        missing.append(int(row.id))
                        continue

                    created = row.created
                    if isinstance(created, str):
                        from infogami.infobase import utils

                        created = utils.parse_datetime(created)
                    timestamp = time.mktime(created.timetuple())
                    refs = {}
                    for size in IMAGE_SIZES:
                        name = _cover_filename(row.id, size)
                        refs[size] = manager.add_file(name, paths[size], timestamp)
                    archived.append((cover, paths, refs))
            finally:
                manager.close()

            if test:
                continue

            # The zips are complete before the database advertises their paths.
            for cover, paths, refs in archived:
                covers_db.mark_archived(cover.id, refs)
                for path in paths.values():
                    os.remove(path)
            for cover_id in missing:
                covers_db.mark_failed(cover_id)


def audit(group_id, chunk_ids=(0, 100), sizes=IMAGE_SIZES):
    """Print which zip batches are present in their archive.org items."""
    scope = range(*(chunk_ids if isinstance(chunk_ids, tuple) else (0, chunk_ids)))
    for size in sizes:
        item = f"{_size_prefix(size)}covers_{int(group_id):04d}"
        missing_files = []
        sys.stdout.write(f"\n{size or 'full'}: ")
        for batch_id in scope:
            filename = os.path.basename(Batch.get_relpath(group_id, batch_id, size))
            if Uploader.is_uploaded(item, filename):
                sys.stdout.write(".")
            else:
                sys.stdout.write("X")
                missing_files.append(filename)
            sys.stdout.flush()
        sys.stdout.write("\n")
        if missing_files:
            print(f"Pending upload to {item}: {' '.join(missing_files)}")
# Coverstore archival

Cover IDs use a fixed-width, 10-digit representation. The first four digits
select a 1,000,000-cover archive.org item and the next two digits select a
10,000-cover zip batch. The remaining four digits identify a cover within that
batch. For example, cover `80001234` is stored as:

- item: `covers_0008`
- batch: `covers_0008_01.zip`
- zip member: `0008001234.jpg`

The size variants use the same item and batch numbers with an `s_`, `m_`, or
`l_` prefix on the item and zip names. Their members end in `-S.jpg`, `-M.jpg`,
or `-L.jpg`, respectively. A cover URL has the form
`https://archive.org/download/<item>/<batch>.zip/<10-digit-cover-id>[-S|-M|-L].jpg`.

## Archival flow

Call `archive.archive(test=False)` after loading the coverstore configuration
to build local, uncompressed batch zips. The database records each cover as
archived and points its filename fields into those local zips. Original local
images are removed only after the zip has closed successfully. Missing images
are marked `failed` and are skipped on later runs.

For each batch, upload and verify its four zip files, then finalize it:

```python
from openlibrary.coverstore.archive import Batch

Batch(8, 1).process_pending(upload=True, finalize=True)
```

Each batch is locked while it is being built or finalized. Upload completion is
checked against the exact zip filename in its archive.org item. Finalization
sets `uploaded=true`, replaces all four filename fields with their canonical
archive.org URLs, and removes the local batch zips. Covers in a failed or
incomplete batch are not marked uploaded.

The `failed` and `uploaded` columns default to false and have indexes named
`cover_failed_idx` and `cover_uploaded_idx`. `archived` indicates that a local
batch zip was successfully built; `uploaded` indicates that its remote upload
was verified and the database now points to archive.org.
